//! Twilight Forest (`twilight`, `genlayer`) vs golden vectors from the verbatim TF 2.7.45 (GTNH) layer classes
//! (`GenLayerTF*`), vanilla 1.7.10 `GenLayer`/`GenLayerZoom`/`GenLayerSmooth`/`GenLayerVoronoiZoom`/`IntCache`, and
//! `TFFeature.generateFeatureFor1Point7` / `getNearestCenterXYZ` copied into a shim class, compiled standalone with
//! OpenJDK 21 (biome objects shimmed to the GTNH 2.9.0 ids; `World.getBiomeGenForCoords` = BiomeCache block of the
//! voronoi layer). Hashes are FNV-1a 64 over the ints (`h ^= v as u32; h *= prime`).
use rwg2_biomes::twilight::*;

fn fnv(v: &[i32]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &x in v {
        h ^= x as u32 as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

