#[test]
fn biome_layers_match_java() {
    let mut n = 0;
    for l in ZOOMED.lines().filter(|l| !l.is_empty()) {
        let f: Vec<&str> = l.split_whitespace().collect();
        let seed: i64 = f[1].parse().unwrap();
        let (x, z, w, h): (i32, i32, i32, i32) = (
            f[2].parse().unwrap(),
            f[3].parse().unwrap(),
            f[4].parse().unwrap(),
            f[5].parse().unwrap(),
        );
        let tf = TwilightForest::new(seed);
        let zoomed = tf.biomes(x, z, w, h);
        assert_eq!(format!("{:x}", fnv(&zoomed)), f[6], "zoomed {l}");
        let unzoomed = tf.biomes_quarter(x >> 2, z >> 2, w, h);
        assert_eq!(format!("{:x}", fnv(&unzoomed)), f[8], "unzoomed {l}");
        n += 1;
    }
    assert_eq!(n, 40);
    for l in BLOCKS.lines().filter(|l| !l.is_empty()) {
        let f: Vec<&str> = l.split_whitespace().collect();
        let seed: i64 = f[1].parse().unwrap();
        let (x, z): (i32, i32) = (f[2].parse().unwrap(), f[3].parse().unwrap());
        let want: Vec<i32> = f[4..].iter().map(|s| s.parse().unwrap()).collect();
        let tf = TwilightForest::new(seed);
        let got = if f[0] == "block" {
            tf.biomes(x, z, 16, 16)
        } else {
            tf.biomes_quarter(x, z, 16, 16)
        };
        assert_eq!(got, want, "{} {seed}", f[0]);
        // per-point queries agree with the window (the stack is window-independent)
        if f[0] == "block" {
            for (i, &b) in want.iter().enumerate() {
                assert_eq!(tf.biome_at(x + (i % 16) as i32, z + (i / 16) as i32), b);
            }
        }
    }
}

#[test]
fn feature_centres_match_java() {
    let want: Vec<(i32, i32)> = CENTERS
        .split_whitespace()
        .map(|p| {
            let (a, b) = p.split_once(',').unwrap();
            (a.parse().unwrap(), b.parse().unwrap())
        })
        .collect();
    let mut i = 0;
    for rz in -6..=6 {
        for rx in -6..=6 {
            assert_eq!(region_center_block(rx, rz), want[i], "region {rx},{rz}");
            let (x, z) = want[i];
            assert!(is_feature_chunk(x >> 4, z >> 4));
            assert_eq!((region_of_chunk(x >> 4), region_of_chunk(z >> 4)), (rx, rz));
            i += 1;
        }
    }
}

#[test]
fn features_match_java() {
    let mut kinds = std::collections::BTreeMap::new();
    for l in FEATURES.lines().filter(|l| !l.is_empty()) {
        let mut it = l.split_whitespace();
        let seed: i64 = it.next().unwrap().parse().unwrap();
        let tf = TwilightForest::new(seed);
        let want: Vec<(u8, i32)> = it
            .map(|p| {
                let (a, b) = p.split_once(':').unwrap();
                (a.parse().unwrap(), b.parse().unwrap())
            })
            .collect();
        let mut i = 0;
        for rz in -6..=6 {
            for rx in -6..=6 {
                let f = tf.feature_for_region(rx, rz);
                assert_eq!(
                    (f.feature.id, f.biome),
                    want[i],
                    "seed {seed} region {rx},{rz}"
                );
                assert_eq!(tf.feature_at_chunk(f.chunk_x, f.chunk_z), Some(f));
                assert_eq!(tf.feature_at_chunk(f.chunk_x + 1, f.chunk_z), None);
                *kinds.entry(f.feature.name).or_insert(0) += 1;
                i += 1;
            }
        }
    }
    println!("feature kinds over 8 seeds × 169 regions: {kinds:?}");
}

#[test]
fn feature_chunk_census_matches_java() {
    for l in FEATURE_CHUNKS.lines().filter(|l| !l.is_empty()) {
        let f: Vec<&str> = l.split_whitespace().collect();
        let seed: i64 = f[1].parse().unwrap();
        let tf = TwilightForest::new(seed);
        let mut n = 0;
        let mut h: u64 = 0xcbf29ce484222325;
        for cz in -100..100 {
            for cx in -100..100 {
                if is_feature_chunk(cx, cz) {
                    n += 1;
                    for v in [cx, cz] {
                        h ^= v as u32 as u64;
                        h = h.wrapping_mul(0x100000001b3);
                    }
                }
            }
        }
        assert_eq!(n.to_string(), f[2]);
        assert_eq!(format!("{h:x}"), f[3]);
        // features_in returns exactly those chunks
        assert_eq!(tf.features_in(-100, -100, 99, 99).len(), n);
    }
}

#[test]
fn timing() {
    let tf = TwilightForest::new(1337);
    let t = std::time::Instant::now();
    let mut s = 0i64;
    for k in 0..16 {
        s += tf
            .biomes(k * 256, 0, 256, 256)
            .iter()
            .map(|&b| b as i64)
            .sum::<i64>();
    }
    let blk = t.elapsed().as_secs_f64() / (16.0 * 65536.0);
    let t = std::time::Instant::now();
    for k in 0..16 {
        s += tf
            .biomes_quarter(k * 256, 0, 256, 256)
            .iter()
            .map(|&b| b as i64)
            .sum::<i64>();
    }
    let q = t.elapsed().as_secs_f64() / (16.0 * 65536.0);
    let t = std::time::Instant::now();
    let fs = tf.features_in(-512, -512, 511, 511);
    let fe = t.elapsed().as_secs_f64() / fs.len() as f64;
    println!(
        "TF: {:.1} ns/block (voronoi), {:.1} ns per 1:4 cell, {:.1} µs/feature ({} features) [{s}]",
        blk * 1e9,
        q * 1e9,
        fe * 1e6,
        fs.len()
    );
}
